      const [n, rules] = args;
      // decide on our own whether any order exists (Kahn's algorithm)
      const after = Array.from({ length: n }, () => []), indeg = new Array(n).fill(0);
      for (const [a, b] of rules) { after[a].push(b); indeg[b]++; }
      const q = [];
      for (let i = 0; i < n; i++) if (indeg[i] === 0) q.push(i);
      for (let h = 0; h < q.length; h++) for (const b of after[q[h]]) if (--indeg[b] === 0) q.push(b);
      const possible = q.length === n;
      if (!Array.isArray(got)) return false;
      if (!possible) return got.length === 0;
      if (got.length !== n) return false;
      const pos = new Array(n).fill(-1);
      for (let i = 0; i < n; i++) {
        const c = got[i];
        if (!Number.isInteger(c) || c < 0 || c >= n || pos[c] !== -1) return false; // out of range or repeated
        pos[c] = i;
      }
      return rules.every(([a, b]) => pos[a] < pos[b]);
    }

