function courseOrder(n: number, rules: number[][]): number[] {
  const after: number[][] = Array.from({ length: n }, () => []);
  for (const [a, b] of rules) after[a].push(b);
  const color = new Array(n).fill(0); // 0 white, 1 grey (on the path), 2 black (finished)
  const finished: number[] = [];
  for (let s = 0; s < n; s++) {
    if (color[s] !== 0) continue;
    color[s] = 1;
    const stack: number[][] = [[s, 0]];
    while (stack.length) {
      const top = stack[stack.length - 1], u = top[0];
      if (top[1] < after[u].length) {
        const v = after[u][top[1]++];
        if (color[v] === 1) return []; // loop
        if (color[v] === 0) { color[v] = 1; stack.push([v, 0]); }
      } else {
        color[u] = 2;
        finished.push(u);
        stack.pop();
      }
    }
  }
  return finished.reverse();
}

