function courseOrder(n: number, rules: number[][]): number[] {
  const after: number[][] = Array.from({ length: n }, () => []);
  const indeg = new Array(n).fill(0);
  for (const [a, b] of rules) { after[a].push(b); indeg[b]++; }
  const order: number[] = [];
  for (let c = 0; c < n; c++) if (indeg[c] === 0) order.push(c);
  for (let head = 0; head < order.length; head++) // the queue is the answer list itself
    for (const b of after[order[head]])
      if (--indeg[b] === 0) order.push(b);
  return order.length === n ? order : [];
}

